class Solution {
    private int check(String s, char startChar) {
        int mismatches = 0;
        char curr = startChar;
        for (int i = 0; i < s.length(); ++i) {
            if (s.charAt(i) != curr) mismatches++;
            curr = (curr == '0') ? '1' : '0';
        }
        return mismatches / 2;
    }

    public int minSwaps(String s) {
        int c0 = 0, c1 = 0;
        for (int i = 0; i < s.length(); ++i) {
            if (s.charAt(i) == '0') c0++;
            else c1++;
        }
        if (Math.abs(c0 - c1) > 1) return -1;

        if (c0 > c1) return check(s, '0');
        if (c1 > c0) return check(s, '1');
        return Math.min(check(s, '0'), check(s, '1'));
    }
}

