var minSwaps = function(s) {
    let c0 = 0, c1 = 0;
    for (const c of s) {
        if (c === '0') c0++;
        else c1++;
    }
    if (Math.abs(c0 - c1) > 1) return -1;

    function check(startChar) {
        let mismatches = 0;
        let curr = startChar;
        for (const c of s) {
            if (c !== curr) mismatches++;
            curr = curr === '0' ? '1' : '0';
        }
        return Math.floor(mismatches / 2);
    }

    if (c0 > c1) return check('0');
    if (c1 > c0) return check('1');
    return Math.min(check('0'), check('1'));
};
